#define main bridge_program_main
#include "bridge.c"
#undef main
#include <assert.h>
int main(int n,char**a){assert(n>1&&init(a[1]));for(int p=0;p<2;p++){select_party(p);for(int i=0;i<4;i++)assert(g_champions[i].cell==((g_party_direction+i)&3));}for(int p=0;p<2;p++){select_party(p);command_set_dragged_icon(p+1);}for(int k=0;k<4;k++){Json j={0};snapshot(&j);json_free(&j);for(int p=0;p<2;p++){select_party(p);assert(command_get_dragged_icon()==p+1);}}puts("PASS simultaneous distinct pending selections survive both-party polling");for(int p=0;p<2;p++){select_party(p);command_set_dragged_icon(-1);}puts("PASS both initial fixtures first two front; all eight identities preserved");
for(int p=0;p<2;p++)for(int d=0;d<4;d++){select_party(p);g_party_direction=d;for(int i=0;i<4;i++){g_champions[i].cell=(d+i)&3;g_champions[i].direction=d;}command_set_dragged_icon(-1);command_process_click(290,6,CLICK_LEFT_PRESS);command_process_click(290,6,CLICK_LEFT_RELEASE);gameloop_run_commands();assert(command_get_dragged_icon()==0);for(int k=0;k<3;k++){Json j={0};snapshot(&j);json_free(&j);select_party(1-p);redraw();select_party(p);assert(command_get_dragged_icon()==0);}command_process_click(290,21,CLICK_LEFT_PRESS);command_process_click(290,21,CLICK_LEFT_RELEASE);gameloop_run_commands();assert(command_get_dragged_icon()==-1);assert(g_champions[0].cell==((d+3)&3)&&g_champions[3].cell==d);for(int i=0;i<4;i++)assert(g_champions[i].direction==d);printf("PASS party%d heading%d original two-click swap survives alternating polls and preserves facing\n",p,d);}return 0;}
